parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "isInvoiceRequest": {
      "type": "boolean",
      "description": "true only if the sender asks for an invoice or places an order with items"
    },
    "customerName": {
      "type": "string",
      "description": "Company or person to bill"
    },
    "customerEmail": {
      "type": "string",
      "description": "Email the invoice should go to, empty if not stated"
    },
    "billingAddress": {
      "type": "string",
      "description": "Full billing address with line breaks, empty if not stated"
    },
    "poNumber": {
      "type": "string",
      "description": "Purchase order or reference number, empty if none"
    },
    "currency": {
      "type": "string",
      "description": "ISO 4217 code if a currency is stated, else empty"
    },
    "lineItems": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "description": {
            "type": "string"
          },
          "quantity": {
            "type": "number"
          },
          "unitPrice": {
            "type": "number",
            "description": "Price for one unit, without tax. Leave out if the email gives no price."
          }
        },
        "required": [
          "description",
          "quantity"
        ]
      }
    },
    "notes": {
      "type": "string",
      "description": "Anything the customer asked to appear on the invoice"
    }
  },
  "required": [
    "isInvoiceRequest",
    "lineItems"
  ]
}

parameters.jsCode:
// Checks what the AI extracted before any money is calculated.
// Money is kept in integer cents the whole way, so totals never drift (no 0.1 + 0.2 bugs).
// Every problem found is collected, so the reviewer sees all of them at once.

const settings = $('Invoice settings').first().json;
const email = $('New invoice request email').item.json;
const extracted = $json.output ?? {};
const problems = [];

if ($json.error) problems.push(`AI extraction failed: ${$json.error}`);

const senderAddress = email.from?.value?.[0]?.address ?? '';
const senderName = email.from?.value?.[0]?.name ?? '';

// "1,200.5" or 1200.5 -> 120050. Accepts up to 2 decimals. Returns null if it is not a plain amount.
const toHundredths = (raw) => {
  const clean = String(raw ?? '').replace(/[\s,$€£]/g, '');
  const m = clean.match(/^(\d+)(?:\.(\d{1,2}))?$/);
  if (!m) return null;
  return Number(m[1]) * 100 + Number((m[2] ?? '').padEnd(2, '0'));
};

const currency = String(settings.currency || 'USD').toUpperCase();

if (extracted.isInvoiceRequest !== true) problems.push('The email does not look like an invoice or order request.');

const customerName = String(extracted.customerName ?? '').trim() || senderName.trim();
if (!customerName) problems.push('No customer name found.');

// Use the address the customer asked for, else reply to the sender.
const customerEmail = String(extracted.customerEmail ?? '').trim() || senderAddress;
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(customerEmail)) problems.push(`Customer email is not valid: "${customerEmail}"`);

const askedCurrency = String(extracted.currency ?? '').trim().toUpperCase();
if (askedCurrency && askedCurrency !== currency) {
  problems.push(`The request is in ${askedCurrency}, but this workflow invoices in ${currency}.`);
}

const rawItems = Array.isArray(extracted.lineItems) ? extracted.lineItems : [];
if (rawItems.length === 0) problems.push('No line items found.');

const items = [];
rawItems.forEach((it, i) => {
  const description = String(it?.description ?? '').trim();
  const qtyHundredths = toHundredths(it?.quantity);
  const unitCents = toHundredths(it?.unitPrice);
  if (!description) problems.push(`Line ${i + 1}: no description.`);
  if (qtyHundredths === null || qtyHundredths === 0) problems.push(`Line ${i + 1}: quantity is missing or not a number (${it?.quantity ?? 'empty'}).`);
  if (unitCents === null) problems.push(`Line ${i + 1}: unit price is missing or not a number (${it?.unitPrice ?? 'empty'}).`);
  if (!description || !qtyHundredths || unitCents === null) return;
  const lineCents = Math.round((qtyHundredths * unitCents) / 100);
  const qtyText = String(qtyHundredths / 100); // 150 -> "1.5"
  items.push({ description, qtyText, unitCents, lineCents });
});

const subtotalCents = items.reduce((sum, it) => sum + it.lineCents, 0);
const taxRateHundredths = toHundredths(settings.taxRatePercent ?? 0) ?? 0; // 8.25% -> 825
const taxCents = Math.round((subtotalCents * taxRateHundredths) / 10000);
const totalCents = subtotalCents + taxCents;

if (items.length > 0 && totalCents <= 0) problems.push('The invoice total is zero.');

// Large invoices always go to a human first.
const approvalLimitCents = toHundredths(settings.autoApproveLimit) ?? 0;
if (approvalLimitCents > 0 && totalCents > approvalLimitCents) {
  problems.push(`Total ${(totalCents / 100).toFixed(2)} ${currency} is above the auto-approve limit of ${(approvalLimitCents / 100).toFixed(2)} ${currency}.`);
}

return {
  json: {
    valid: problems.length === 0,
    problems,
    problemsText: problems.join(' | '),
    messageId: email.id,
    threadId: email.threadId,
    subject: email.subject ?? '',
    sender: senderAddress,
    receivedAt: email.date ?? $now.toISO(),
    customerName,
    customerEmail,
    billingAddress: String(extracted.billingAddress ?? '').trim(),
    poNumber: String(extracted.poNumber ?? '').trim(),
    notes: String(extracted.notes ?? '').trim(),
    currency,
    taxRateHundredths,
    items,
    subtotalCents,
    taxCents,
    totalCents,
  },
};

