parameters.jsCode:
// Gives each new request the next invoice number and builds the invoice HTML.
// Numbers look like INV-2026-0001 and restart every year. The next number is
// one more than the highest number already in the "Invoices" log tab.
// A request whose email ID is already in the log is marked as a duplicate.
// Every value that came from the email is HTML-escaped before it goes into the invoice.

const settings = $('Invoice settings').first().json;
const logRows = $input.all().map((i) => i.json).filter((r) => r && r['Invoice number']);
const requests = $('Validate items and total in cents').all().filter((i) => i.json.valid);

const prefix = String(settings.invoicePrefix || 'INV').trim();
const year = $now.toFormat('yyyy');
const series = `${prefix}-${year}-`;

let lastNumber = 0;
for (const row of logRows) {
  const value = String(row['Invoice number']);
  if (value.startsWith(series)) {
    const n = Number(value.slice(series.length));
    if (Number.isInteger(n) && n > lastNumber) lastNumber = n;
  }
}
const alreadyInvoiced = new Map(logRows.map((r) => [String(r['Source email ID'] ?? ''), String(r['Invoice number'])]));

const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
const nl2br = (s) => esc(s).replace(/\r?\n/g, '<br>');

const money = (cents, currency) => {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const whole = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}${currency} ${whole}.${String(abs % 100).padStart(2, '0')}`;
};
const plain = (cents) => (cents / 100).toFixed(2); // for the log sheet

const issued = $now;
const due = issued.plus({ days: Number(settings.paymentTermsDays) || 0 });

return requests.map((req) => {
  const r = req.json;
  const duplicateOf = alreadyInvoiced.get(String(r.messageId)) ?? '';
  if (duplicateOf) {
    return { json: { duplicate: true, duplicateOf, messageId: r.messageId, customerName: r.customerName } };
  }

  lastNumber += 1;
  const invoiceNumber = `${series}${String(lastNumber).padStart(4, '0')}`;
  const c = r.currency;

  const itemRows = r.items
    .map(
      (it) => `<tr>
        <td>${esc(it.description)}</td>
        <td class="num">${esc(it.qtyText)}</td>
        <td class="num">${esc(money(it.unitCents, c))}</td>
        <td class="num">${esc(money(it.lineCents, c))}</td>
      </tr>`,
    )
    .join('');

  const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>Invoice ${esc(invoiceNumber)}</title>
<style>
  body { font-family: -apple-system, "Segoe UI", Helvetica, Arial, sans-serif; color: #1f2937; font-size: 13px; margin: 0; }
  .top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 36px; }
  h1 { font-size: 30px; margin: 0 0 6px; letter-spacing: 1px; color: #111827; }
  .muted { color: #6b7280; }
  .parties { display: flex; gap: 48px; margin-bottom: 28px; }
  .parties > div { flex: 1; }
  .parties h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #6b7280; margin: 0 0 6px; }
  table { width: 100%; border-collapse: collapse; }
  th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #6b7280; border-bottom: 2px solid #111827; padding: 8px 6px; }
  td { padding: 10px 6px; border-bottom: 1px solid #e5e7eb; vertical-align: top; }
  tr { page-break-inside: avoid; }
  .num { text-align: right; white-space: nowrap; }
  .totals { margin-left: auto; width: 320px; margin-top: 18px; }
  .totals td { border: 0; padding: 4px 6px; }
  .totals .grand td { border-top: 2px solid #111827; font-size: 16px; font-weight: 700; padding-top: 10px; }
  .box { margin-top: 28px; padding: 14px 16px; background: #f3f4f6; border-radius: 6px; }
</style></head>
<body>
  <div class="top">
    <div><h1>INVOICE</h1><div class="muted">${esc(invoiceNumber)}</div></div>
    <div style="text-align:right">
      <div><strong>Issued:</strong> ${esc(issued.toFormat('d LLL yyyy'))}</div>
      <div><strong>Due:</strong> ${esc(due.toFormat('d LLL yyyy'))}</div>
      ${r.poNumber ? `<div><strong>Your PO:</strong> ${esc(r.poNumber)}</div>` : ''}
    </div>
  </div>
  <div class="parties">
    <div><h3>From</h3><strong>${esc(settings.sellerName)}</strong><br>${nl2br(settings.sellerAddress)}<br>${esc(settings.sellerEmail)}</div>
    <div><h3>Bill to</h3><strong>${esc(r.customerName)}</strong><br>${r.billingAddress ? nl2br(r.billingAddress) + '<br>' : ''}${esc(r.customerEmail)}</div>
  </div>
  <table>
    <colgroup><col style="width:52%"><col style="width:12%"><col style="width:18%"><col style="width:18%"></colgroup>
    <thead><tr><th>Description</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Amount</th></tr></thead>
    <tbody>${itemRows}</tbody>
  </table>
  <table class="totals">
    <tr><td>Subtotal</td><td class="num">${esc(money(r.subtotalCents, c))}</td></tr>
    <tr><td>Tax (${esc((r.taxRateHundredths / 100).toString())}%)</td><td class="num">${esc(money(r.taxCents, c))}</td></tr>
    <tr class="grand"><td>Total due</td><td class="num">${esc(money(r.totalCents, c))}</td></tr>
  </table>
  <div class="box"><strong>How to pay</strong><br>${nl2br(settings.paymentInstructions)}<br>Please quote ${esc(invoiceNumber)} as the payment reference.</div>
  ${r.notes ? `<div class="box"><strong>Notes</strong><br>${nl2br(r.notes)}</div>` : ''}
</body></html>`;

  return {
    json: {
      duplicate: false,
      invoiceNumber,
      fileName: `${invoiceNumber}.pdf`,
      html,
      messageId: r.messageId,
      threadId: r.threadId,
      customerName: r.customerName,
      customerEmail: r.customerEmail,
      currency: c,
      subtotal: plain(r.subtotalCents),
      tax: plain(r.taxCents),
      total: plain(r.totalCents),
      totalFormatted: money(r.totalCents, c),
      issuedDate: issued.toFormat('yyyy-MM-dd'),
      dueDate: due.toFormat('yyyy-MM-dd'),
      dueDateText: due.toFormat('d LLL yyyy'),
    },
  };
});

